<?php declare(strict_types=1); ?>
<section class="page-wrap core-page" aria-labelledby="general-title">
<p class="ledger-entry-link"><a href="<?= pl_e(pl_url('/reports/account')) ?>">Account ledger &amp; running balances <?= pl_icon('arrow-right') ?></a></p>
<div class="page-heading"><div><p class="eyebrow">Accounting core</p><h1 id="general-title">General journals</h1><p class="muted">Save the entry, review its lines, then post to your books.</p></div><?php if (pl_can_write($company)): ?><a class="button primary" href="<?= pl_e(pl_url('/general-journals/new')) ?>"><?= pl_icon('plus') ?> New journal</a><?php endif; ?></div>
<form method="get" action="<?= pl_e(pl_url('/general-journals')) ?>" class="filter-bar" data-fold="filters">
<?php pl_ui_list_controls($filters); ?>
<label class="field"><span class="sr-only">Journal status</span><select class="select" name="status"><?php foreach (['all'=>'All statuses','draft'=>'Drafts','posted'=>'Posted','reversed'=>'Reversed'] as $key=>$label): ?><option value="<?= pl_e($key) ?>"<?= $filters['status'] === $key ? ' selected' : '' ?>><?= pl_e($label) ?></option><?php endforeach; ?></select></label>
